CREATE OR REPLACE FUNCTION public.attendance_display(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.events; t timestamptz; r integer; opened timestamptz; slot_start timestamptz; expiry timestamptz; seconds integer; token_value text; fingerprint text;
begin
  if not public.can_edit_content() then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into e from public.events where code=p_code for share;
  if not found then raise exception 'Not found'; end if;
  t:=clock_timestamp(); r:=attendance_private.round_at(e,t);
  if r is null then return jsonb_build_object('title',e.title,'server_time',t,'round',null,'token',null,'config',e.attendance_config); end if;
  seconds:=(e.attendance_config->>'qr_seconds')::integer;
  opened:=(e.attendance_config->>case r when 1 then 'round_one' else 'round_two' end)::timestamptz;
  slot_start:=opened+floor(extract(epoch from t-opened)/seconds)*seconds*interval '1 second';
  expiry:=least(slot_start+seconds*interval '1 second',opened+attendance_private.duration(e.attendance_config)); fingerprint:=md5(e.attendance_config::text);
  delete from attendance_private.tokens where event_id=e.id and expires_at<t-interval '2 hours';
  insert into attendance_private.tokens(event_id,round,slot,config_hash,expires_at) values(e.id,r,slot_start,fingerprint,expiry) on conflict do nothing;
  select token into token_value from attendance_private.tokens where event_id=e.id and round=r and slot=slot_start and config_hash=fingerprint;
  return jsonb_build_object('title',e.title,'server_time',t,'round',r,'token','HSV1:'||token_value,'expires_at',expiry,'closes_at',opened+attendance_private.duration(e.attendance_config),'qr_seconds',seconds);
end $function$

CREATE OR REPLACE FUNCTION public.attendance_edit(p_code text, p_browser_id uuid, p_secret text, p_name text, p_student_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r attendance_private.records;
begin
  if p_secret is null or p_secret !~ '^[0-9a-f]{64}$' then return '{"ok":false}'::jsonb; end if;
  select x.* into r from attendance_private.records x join public.events e on e.id=x.event_id
    where e.code=p_code and x.browser_id=p_browser_id and x.key_hash=sha256(convert_to(p_secret,'UTF8')) for update of x;
  if not found then return '{"ok":false}'::jsonb; end if;
  p_name:=btrim(p_name); p_student_id:=upper(btrim(p_student_id));
  if p_name is null or length(p_name) not between 2 and 120 or p_student_id is null or p_student_id !~ '^[A-Z0-9][A-Z0-9._-]{2,29}$' then return '{"ok":false}'::jsonb; end if;
  if r.full_name is distinct from p_name or r.student_id is distinct from p_student_id then
    insert into attendance_private.edits(record_id,old_name,old_student_id,new_name,new_student_id) values(r.id,r.full_name,r.student_id,p_name,p_student_id);
    update attendance_private.records set full_name=p_name,student_id=p_student_id,updated_at=clock_timestamp() where id=r.id returning * into r;
  end if;
  return jsonb_build_object('ok',true,'record',attendance_private.result(r));
exception when unique_violation or check_violation then return '{"ok":false}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.attendance_own(p_code text, p_browser_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r attendance_private.records;
begin
  if p_secret is null or p_secret !~ '^[0-9a-f]{64}$' then return null; end if;
  select x.* into r from attendance_private.records x join public.events e on e.id=x.event_id
    where e.code=p_code and x.browser_id=p_browser_id and x.key_hash=sha256(convert_to(p_secret,'UTF8'));
  if not found then return null; end if;
  return attendance_private.result(r);
end $function$

CREATE OR REPLACE FUNCTION attendance_private.validate_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb:=new.attendance_config; a timestamptz; b timestamptz;
begin
  if new.default_invitation_id is not null and not exists(select 1 from public.event_guests where id=new.default_invitation_id and event_id=new.id) then
    raise exception 'Thiệp mặc định không thuộc sự kiện.' using errcode='23514';
  end if;

    if c is null then return new; end if;
    if c ? 'duration_minutes' and (
      jsonb_typeof(c->'duration_minutes') is distinct from 'number'
      or (c->>'duration_minutes')::numeric not between 1 and 60
      or (c->>'duration_minutes')::numeric <> trunc((c->>'duration_minutes')::numeric)
    ) then
      raise exception 'Thời lượng mỗi đợt phải là số nguyên từ 1 đến 60 phút.' using errcode='23514';
    end if;

  if jsonb_typeof(c) <> 'object' or c - array['enabled','radius_m','qr_seconds','latitude','longitude','pin_confirmed','pin_source','round_one','round_two','duration_minutes'] <> '{}'::jsonb
    or not c ?& array['enabled','radius_m','qr_seconds','latitude','longitude','pin_confirmed','pin_source','round_one','round_two']
    or jsonb_typeof(c->'enabled') <> 'boolean' or jsonb_typeof(c->'pin_confirmed') <> 'boolean'
    or jsonb_typeof(c->'radius_m') <> 'number' or jsonb_typeof(c->'qr_seconds') <> 'number'
    or (c->>'radius_m')::numeric not between 10 and 1000 or (c->>'radius_m')::numeric <> trunc((c->>'radius_m')::numeric)
    or (c->>'qr_seconds')::numeric not between 3 and 60 or (c->>'qr_seconds')::numeric <> trunc((c->>'qr_seconds')::numeric)
    or jsonb_typeof(c->'pin_source') <> 'string' or length(c->>'pin_source') > 5000
    or jsonb_typeof(c->'round_one') <> 'string' or jsonb_typeof(c->'round_two') <> 'string'
    or (c->'latitude' <> 'null'::jsonb and (jsonb_typeof(c->'latitude') <> 'number' or (c->>'latitude')::numeric not between -85 and 85))
    or (c->'longitude' <> 'null'::jsonb and (jsonb_typeof(c->'longitude') <> 'number' or (c->>'longitude')::numeric not between -180 and 180)) then
    raise exception 'Cấu hình điểm danh không hợp lệ.' using errcode='23514';
  end if;
  if (c->>'enabled')::boolean and new.event_type='invitation' then
    if not (c->>'pin_confirmed')::boolean or c->'latitude'='null'::jsonb or c->'longitude'='null'::jsonb
      or (c->>'pin_source')::jsonb is distinct from attendance_private.location_source(new) then
      raise exception 'Kiểm tra và xác nhận ghim cho địa điểm hiện tại.' using errcode='23514';
    end if;
    a:=(c->>'round_one')::timestamptz; b:=(c->>'round_two')::timestamptz;
    if a is null or b is null or not isfinite(a) or not isfinite(b)
      or a<new.starts_at or b<new.starts_at or a+attendance_private.duration(c)>new.ends_at or b+attendance_private.duration(c)>new.ends_at
      or a+attendance_private.duration(c)>b then
      raise exception 'Hai đợt không được chồng nhau và phải nằm trong thời gian sự kiện.' using errcode='23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.attendance_status(p_code text, p_alias text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.events; t timestamptz:=clock_timestamp(); r integer; eligible boolean;
begin
  select * into e from public.events where code=p_code and status='published';
  eligible:=found and e.event_type='invitation' and coalesce((e.attendance_config->>'enabled')::boolean,false)
    and exists(select 1 from public.invitation_aliases a join public.event_guests g on g.id=a.event_guest_id and g.event_id=a.event_id where a.event_id=e.id and a.alias=p_alias and g.kind='group');
  if not eligible then return jsonb_build_object('eligible',false,'server_time',t,'round',null,'closes_at',null); end if;
  r:=attendance_private.round_at(e,t);
  return jsonb_build_object('eligible',true,'server_time',t,'round',r,'closes_at',case when r is not null then (e.attendance_config->>case r when 1 then 'round_one' else 'round_two' end)::timestamptz+attendance_private.duration(e.attendance_config) end,
    'radius_m',e.attendance_config->'radius_m','latitude',e.attendance_config->'latitude','longitude',e.attendance_config->'longitude');
end $function$

CREATE OR REPLACE FUNCTION public.attendance_submit(p_code text, p_alias text, p_browser_id uuid, p_secret text, p_name text, p_student_id text, p_token text, p_position jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.events; g uuid; r attendance_private.records; t timestamptz; round_number integer; c jsonb;
  lat double precision; lng double precision; accuracy double precision; age double precision; distance double precision; fix_time timestamptz;
begin
  if p_browser_id is null or p_secret is null or p_secret !~ '^[0-9a-f]{64}$' then return '{"ok":false}'::jsonb; end if;
  select * into e from public.events where code=p_code for share;
  if not found then return '{"ok":false}'::jsonb; end if;
  perform pg_advisory_xact_lock(hashtextextended(e.id::text||p_browser_id::text,0));
  t:=clock_timestamp(); round_number:=attendance_private.round_at(e,t); c:=e.attendance_config;
  if round_number is null then return '{"ok":false}'::jsonb; end if;
  select eg.id into g from public.invitation_aliases a join public.event_guests eg on eg.id=a.event_guest_id and eg.event_id=a.event_id
    where a.event_id=e.id and a.alias=p_alias and eg.kind='group';
  if g is null then return '{"ok":false}'::jsonb; end if;
  if not exists(select 1 from attendance_private.tokens where event_id=e.id and round=round_number and token=substring(p_token from 6)
    and p_token like 'HSV1:%' and config_hash=md5(c::text) and t>=slot and t<expires_at+interval '1 second') then return '{"ok":false}'::jsonb; end if;
  lat:=(p_position->>'latitude')::double precision; lng:=(p_position->>'longitude')::double precision; accuracy:=(p_position->>'accuracy')::double precision;
  fix_time:=(p_position->>'captured_at')::timestamptz; age:=extract(epoch from t-fix_time);
  if lat is null or lng is null or accuracy is null or age is null or not isfinite(fix_time) or lat not between -90 and 90 or lng not between -180 and 180
    or accuracy not between 0.000001 and least(50,(c->>'radius_m')::double precision/2) or age not between -5 and 30 then return '{"ok":false}'::jsonb; end if;
  distance:=6371000*2*asin(least(1,sqrt(power(sin(radians(lat-(c->>'latitude')::double precision)/2),2)
    +cos(radians(lat))*cos(radians((c->>'latitude')::double precision))*power(sin(radians(lng-(c->>'longitude')::double precision)/2),2))));
  if distance>(c->>'radius_m')::double precision then return '{"ok":false}'::jsonb; end if;
  p_name:=btrim(p_name); p_student_id:=upper(btrim(p_student_id));
  if p_name is null or length(p_name) not between 2 and 120 or p_student_id is null or p_student_id !~ '^[A-Z0-9][A-Z0-9._-]{2,29}$' then return '{"ok":false}'::jsonb; end if;
  -- Serialize only the browser's successful binding path. Unique MSSV protects cross-browser races.
  select * into r from attendance_private.records where event_id=e.id and browser_id=p_browser_id for update;
  if found then
    if r.key_hash<>sha256(convert_to(p_secret,'UTF8')) or r.student_id<>p_student_id or r.full_name<>p_name
      or (round_number=1 and r.round_one_at is not null) or (round_number=2 and r.round_two_at is not null) then return '{"ok":false}'::jsonb; end if;
    update attendance_private.records set round_one_at=case when round_number=1 then t else round_one_at end,
      round_two_at=case when round_number=2 then t else round_two_at end,updated_at=t where id=r.id returning * into r;
  else
    insert into attendance_private.records(event_id,invitation_id,browser_id,key_hash,full_name,student_id,round_one_at,round_two_at)
      values(e.id,g,p_browser_id,sha256(convert_to(p_secret,'UTF8')),p_name,p_student_id,case when round_number=1 then t end,case when round_number=2 then t end) returning * into r;
  end if;
  return jsonb_build_object('ok',true,'round',round_number,'record',attendance_private.result(r));
exception when unique_violation or check_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return '{"ok":false}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.begin_editor_add(p_actor uuid, p_email text, p_request_id uuid, p_allow_invite boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare email_value text:=lower(btrim(p_email)); target_user auth.users; op public.editor_add_operations; token uuid:=gen_random_uuid();
begin
  perform pg_advisory_xact_lock(194827,112);
  lock table public.admin_users in share mode;
  if not exists(select 1 from public.admin_users a join auth.users u on u.id=a.user_id where a.user_id=p_actor and coalesce(u.is_anonymous,false)=false and (u.banned_until is null or u.banned_until<=now())) then raise exception 'Admin required' using errcode='42501'; end if;
  if p_request_id is null or email_value is null or length(email_value)>254 or email_value !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Invalid email/request' using errcode='22023'; end if;
  if (select count(*) from auth.users where lower(email)=email_value)>1 then return jsonb_build_object('state','ambiguous_account'); end if;
  select * into target_user from auth.users where lower(email)=email_value;
  if target_user.id is not null and (coalesce(target_user.is_anonymous,false) or target_user.banned_until>now()) then return jsonb_build_object('state','account_ineligible'); end if;
  if exists(select 1 from public.admin_users where user_id=target_user.id) then return jsonb_build_object('state','admin_protected'); end if;
  select * into op from public.editor_add_operations where email=email_value for update;
  if op.request_id=p_request_id and (op.state='revoked' or (op.state='granted' and not exists(select 1 from public.editor_users where user_id=target_user.id))) then
    return jsonb_build_object('state','role_changed');
  end if;
  if exists(select 1 from public.editor_users where user_id=target_user.id) then
    return jsonb_build_object('state','already_editor','account_status',case when target_user.email_confirmed_at is not null then 'confirmed' when target_user.invited_at is not null then 'invited' else 'unconfirmed' end);
  end if;
  if op.lease is not null and op.lease_until>now() then return jsonb_build_object('state','processing'); end if;
  if target_user.id is null and op.email is not null then
    update public.editor_add_operations set state='delivery_unknown',lease=null,lease_until=null,updated_at=clock_timestamp() where email=email_value;
    return jsonb_build_object('state','delivery_unknown');
  end if;
  if target_user.id is null and not coalesce(p_allow_invite,false) then return jsonb_build_object('state','invitation_not_ready'); end if;
  insert into public.editor_add_operations(email,actor,request_id,lease,lease_until,state,target)
    values(email_value,p_actor,p_request_id,token,now()+interval '90 seconds',case when target_user.id is null then 'sending' else 'granting' end,target_user.id)
    on conflict(email) do update set actor=excluded.actor,request_id=excluded.request_id,lease=excluded.lease,lease_until=excluded.lease_until,state=excluded.state,target=excluded.target,updated_at=clock_timestamp();
  return jsonb_build_object('state',case when target_user.id is null then 'invite' else 'grant' end,'lease',token,'target',target_user.id);
end $function$

CREATE OR REPLACE FUNCTION public.duplicate_event(p_source_id uuid, p_copy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  source public.events;
  copied public.events;
  recipient public.event_guests;
  source_data jsonb;
  copy_data jsonb;
  candidate text;
  suffix text;
  sequence integer := 1;
  reserved boolean;
  recipient_id uuid;
  default_id uuid;
begin
  if not coalesce(public.can_edit_content(), false) then
    raise exception 'Content access required' using errcode = '42501';
  end if;
  if p_source_id is null or p_copy_id is null or p_source_id = p_copy_id then
    raise exception 'Invalid duplication request' using errcode = '22023';
  end if;

  -- save_event locks the source before reserving its code; use the same order.
  select * into source from public.events where id = p_source_id for share;
  if not found then raise exception 'Source event not found' using errcode = 'P0002'; end if;
  perform pg_advisory_xact_lock(110110);
  select * into copied from public.events where id = p_copy_id;
  if found then
    if copied.duplicated_from_id is distinct from p_source_id then
      raise exception 'Invalid duplication request' using errcode = '22023';
    end if;
    return public.event_payload_v110(copied);
  end if;

  loop
    suffix := '-copy' || case when sequence = 1 then '' else '-' || sequence::text end;
    candidate := rtrim(left(source.code, 80 - length(suffix)), '-') || suffix;
    reserved := exists(select 1 from public.events where code = candidate);
    -- Some installations retain historical event codes; never reuse those links.
    if not reserved and to_regclass('public.event_codes') is not null then
      execute 'select exists(select 1 from public.event_codes where code = $1)'
        into reserved using candidate;
    end if;
    exit when not reserved;
    sequence := sequence + 1;
    if sequence > 10000 then raise exception 'Không còn mã bản sao phù hợp.'; end if;
  end loop;

  source_data := to_jsonb(source);
  copy_data := source_data || jsonb_build_object(
    'id', p_copy_id, 'code', candidate, 'duplicated_from_id', source.id,
    'created_at', clock_timestamp(), 'updated_at', clock_timestamp(),
    'default_invitation_id', null
  );
  insert into public.events select (jsonb_populate_record(null::public.events, copy_data)).*
    returning * into copied;

  for recipient in select * from public.event_guests where event_id = source.id
    order by created_at, id for share loop
    recipient_id := gen_random_uuid();
    insert into public.event_guests
      select (jsonb_populate_record(null::public.event_guests, to_jsonb(recipient) ||
        jsonb_build_object('id', recipient_id, 'event_id', copied.id,
          'created_at', clock_timestamp(), 'updated_at', clock_timestamp()))).*;
    -- Only the snapshot primary alias is currently routable; the directory may have changed.
    insert into public.invitation_aliases(event_id, event_guest_id, alias)
      values(copied.id, recipient_id, recipient.primary_alias);
    if recipient.id::text = source_data->>'default_invitation_id' then
      default_id := recipient_id;
    end if;
  end loop;

  insert into public.event_agenda_items
    select (jsonb_populate_record(null::public.event_agenda_items, to_jsonb(item) ||
      jsonb_build_object('id', gen_random_uuid(), 'event_id', copied.id,
        'created_at', clock_timestamp(), 'updated_at', clock_timestamp()))).*
    from public.event_agenda_items item where item.event_id = source.id;
  if source_data ? 'default_invitation_id' then
    execute 'update public.events set default_invitation_id = $1 where id = $2'
      using default_id, copied.id;
  end if;

  -- Content, media references, publication and attendance configuration are copied.
  -- Attendance records, browser bindings, issued QR tokens and edit history belong to their event.
  select * into copied from public.events where id = copied.id;
  return public.event_payload_v110(copied);
end $function$

CREATE OR REPLACE FUNCTION public.finish_editor_add(p_actor uuid, p_email text, p_lease uuid, p_target uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare email_value text:=lower(btrim(p_email)); op public.editor_add_operations; target_user auth.users;
begin
  perform pg_advisory_xact_lock(194827,112);
  lock table public.admin_users in share mode;
  select * into op from public.editor_add_operations where email=email_value for update;
  if op.state='revoked' then return jsonb_build_object('state','role_changed'); end if;
  if op.email is null or op.lease is distinct from p_lease or op.lease is null or op.actor<>p_actor then return jsonb_build_object('state','processing'); end if;
  if p_target is null then
    update public.editor_add_operations set state='delivery_unknown',lease=null,lease_until=null,updated_at=clock_timestamp() where email=email_value;
    return jsonb_build_object('state','delivery_unknown');
  end if;
  select * into target_user from auth.users where id=p_target and lower(email)=email_value;
  if target_user.id is null or coalesce(target_user.is_anonymous,false) or target_user.banned_until>now()
     or exists(select 1 from public.admin_users where user_id=p_target)
     or not exists(select 1 from public.admin_users a join auth.users u on u.id=a.user_id where a.user_id=p_actor and coalesce(u.is_anonymous,false)=false and (u.banned_until is null or u.banned_until<=now())) then
    update public.editor_add_operations set state='grant_failed',lease=null,lease_until=null,updated_at=clock_timestamp() where email=email_value;
    return jsonb_build_object('state','grant_failed');
  end if;
  begin
    insert into public.editor_users(user_id) values(p_target) on conflict(user_id) do nothing;
    update public.editor_add_operations set state='granted',target=p_target,lease=null,lease_until=null,updated_at=clock_timestamp() where email=email_value;
  exception when others then
    update public.editor_add_operations set state='grant_failed',target=p_target,lease=null,lease_until=null,updated_at=clock_timestamp() where email=email_value;
    return jsonb_build_object('state','grant_failed');
  end;
  return jsonb_build_object('state','granted','account_status',case when target_user.email_confirmed_at is not null then 'confirmed' when target_user.invited_at is not null then 'invited' else 'unconfirmed' end);
end $function$

CREATE OR REPLACE FUNCTION public.guard_music_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.music_path is not null then
  perform 1 from storage.objects where bucket_id='bookclub-music' and name=new.music_path for key share;
  if not found then raise exception 'Music object missing' using errcode='23503';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.guest_order_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (to_jsonb(new)-'display_order'-'updated_at') is distinct from (to_jsonb(old)-'display_order'-'updated_at') then
  new.updated_at:=clock_timestamp();
 else new.updated_at:=old.updated_at;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.reorder_guests(p_expected uuid[], p_order uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_ids uuid[];
begin
  if not public.can_edit_content() then raise exception 'Admin required' using errcode='42501'; end if;
  if p_expected is null or p_order is null then raise exception 'Guest IDs required' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(194827,110);
  select coalesce(array_agg(id order by display_order,id),array[]::uuid[]) into current_ids from public.guests;
  if current_ids is distinct from p_expected then raise exception 'Guest order changed; reload before retry' using errcode='40001'; end if;
  if cardinality(p_order) <> cardinality(current_ids)
     or cardinality(p_order) <> (select count(distinct id) from unnest(p_order) id)
     or exists(select id from unnest(current_ids) id except select id from unnest(p_order) id) then
    raise exception 'Invalid guest order' using errcode='22023';
  end if;
  update public.guests g set display_order=x.position from unnest(p_order) with ordinality x(id,position)
    where g.id=x.id and g.display_order is distinct from x.position;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_event(p_event jsonb, p_guest_ids uuid[], p_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v public.events; old_event public.events; g public.guests; eg_id uuid; base_alias text; candidate text; n integer; first_alias text; item jsonb; edit jsonb; target uuid; alias_value text;
begin
  if not public.can_edit_content() then raise exception 'Admin required' using errcode='42501'; end if;
  if p_guest_ids is null then raise exception 'Guest IDs required'; end if;
  if cardinality(p_guest_ids) <> (select count(distinct x) from unnest(p_guest_ids) x) then raise exception 'Duplicate guest'; end if;
  if exists(select 1 from unnest(p_guest_ids) x where not exists(select 1 from public.guests directory where directory.id=x)) then raise exception 'Unknown guest'; end if;
  if p_id is not null then
    select * into old_event from public.events where id=p_id for update;
    if not found then raise exception 'Event not found'; end if;
    if p_expected_updated_at is distinct from old_event.updated_at then raise exception 'Concurrent update' using errcode='40001'; end if;

  end if;
  if exists(select 1 from public.guests directory where directory.id=any(p_guest_ids) and not directory.active and not exists(select 1 from public.event_guests eg where eg.event_id=p_id and eg.guest_id=directory.id)) then raise exception 'Inactive guest'; end if;
  if p_id is null and coalesce(p_event->>'code','')='' then p_event:=p_event||jsonb_build_object('code',trim(both '-' from left(public.slug_v110(p_event->>'title'),80))); end if;

  if p_event ? 'event_type' and (p_event->>'event_type' is null or p_event->>'event_type' not in ('invitation','congratulation')) then raise exception 'Invalid event type' using errcode='23514'; end if;
  if p_event ? 'theme' and not public.valid_event_theme(p_event->'theme') then raise exception 'Invalid event theme' using errcode='23514'; end if;
  v := jsonb_populate_record(null::public.events,p_event);
    v.attendance_config:=case when p_event ? 'attendance_config' then nullif(p_event->'attendance_config','null'::jsonb) else old_event.attendance_config end;
    v.default_invitation_id:=case when p_event ? 'default_invitation_id' then (p_event->>'default_invitation_id')::uuid else old_event.default_invitation_id end;
    v.status:=coalesce(old_event.status,'draft');

  v.event_type:=coalesce(v.event_type,old_event.event_type,'invitation');
  v.theme:=coalesce(v.theme,old_event.theme,'{"version":1,"primary":"#174b78"}'::jsonb);
  
  if p_id is null then
    insert into public.events(code,title,description,starts_at,ends_at,status,venue_name,address,directions,latitude,longitude,place_id,maps_url,location_method,venue_image_path,quote_one,quote_two,description_rich,youtube_url,music_path,event_type,theme,attendance_config,default_invitation_id)
    values(v.code,v.title,coalesce(v.description,''),v.starts_at,v.ends_at,v.status,coalesce(v.venue_name,''),coalesce(v.address,''),coalesce(v.directions,''),v.latitude,v.longitude,coalesce(v.place_id,''),coalesce(v.maps_url,''),coalesce(v.location_method,'url'),v.venue_image_path,coalesce(v.quote_one,''),v.quote_two,v.description_rich,nullif(v.youtube_url,''),v.music_path,v.event_type,v.theme,v.attendance_config,v.default_invitation_id) returning * into v;
  else
    update public.events set attendance_config=v.attendance_config,default_invitation_id=v.default_invitation_id,event_type=v.event_type,theme=v.theme,music_path=case when p_event ? 'music_path' then nullif(v.music_path,'') else old_event.music_path end, youtube_url=case when p_event ? 'youtube_url' then nullif(v.youtube_url,'') else old_event.youtube_url end, description_rich=case when p_event ? 'description_rich' then v.description_rich else old_event.description_rich end, quote_one=case when p_event ? 'quote_one' then coalesce(v.quote_one,'') else old_event.quote_one end, quote_two=case when p_event ? 'quote_two' then v.quote_two else old_event.quote_two end, code=v.code,location_method=v.location_method,venue_image_path=v.venue_image_path,title=v.title,description=coalesce(v.description,''),starts_at=v.starts_at,ends_at=v.ends_at,status=v.status,venue_name=coalesce(v.venue_name,''),address=coalesce(v.address,''),directions=coalesce(v.directions,''),latitude=v.latitude,longitude=v.longitude,place_id=coalesce(v.place_id,''),maps_url=coalesce(v.maps_url,'') where id=p_id returning * into v;
  end if;
  delete from public.event_guests where event_id=v.id and not(guest_id=any(p_guest_ids));
  for g in select * from public.guests where id=any(p_guest_ids) order by id loop
    if exists(select 1 from public.event_guests where event_id=v.id and guest_id=g.id) then continue; end if;
    eg_id := gen_random_uuid(); first_alias:=g.primary_alias;
    if exists(select 1 from public.invitation_aliases where event_id=v.id and alias=first_alias) then raise exception 'Primary alias conflict: review existing invitation aliases' using errcode='23505'; end if;
    insert into public.event_guests(id,event_id,guest_id,salutation,name,description,kind,primary_alias) values(eg_id,v.id,g.id,g.salutation,g.name,g.description,g.kind,first_alias);
    insert into public.invitation_aliases(event_id,event_guest_id,alias) values(v.id,eg_id,first_alias);

  end loop;
  n:=0;
 if p_event ? 'agenda' then
   if jsonb_typeof(p_event->'agenda')<>'array' or jsonb_array_length(p_event->'agenda')>100 then raise exception 'Invalid agenda'; end if;
   -- Only unchanged legacy milestones may retain a missing end time.
   for item in select value from jsonb_array_elements(p_event->'agenda') loop
    if item->>'end_time' is null and not exists(select 1 from public.event_agenda_items old_item where old_item.event_id=v.id and old_item.end_time is null and old_item.time=item->>'time' and old_item.description=item->>'description') then
     raise exception 'End time required for new or edited milestone' using errcode='23514';
    end if;
   end loop;
   delete from public.event_agenda_items where event_id=v.id;
   for item in select value from jsonb_array_elements(p_event->'agenda') loop
     insert into public.event_agenda_items(event_id,time,end_time,icon,description,highlight,sort_order) values(v.id,item->>'time',item->>'end_time',coalesce(item->>'icon','book'),item->>'description',coalesce((item->>'highlight')::boolean,false),n); n:=n+1;
   end loop;
 end if;
 if p_event ? 'invitation_edits' and p_event->'invitation_edits'<>'[]'::jsonb then raise exception 'Secondary alias editing is disabled' using errcode='42501'; end if;
  select * into v from public.events where id=v.id; return public.event_payload_v110(v);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_editor_role(p_actor uuid, p_target uuid, p_grant boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform pg_advisory_xact_lock(194827,112);
 lock table public.admin_users in share mode;
 if not exists(select 1 from public.admin_users where user_id=p_actor) then raise exception 'Admin required' using errcode='42501';end if;
 if exists(select 1 from public.admin_users where user_id=p_target) then raise exception 'Admin targets locked' using errcode='42501';end if;
 if not exists(select 1 from auth.users where id=p_target) then raise exception 'Account not found' using errcode='22023';end if;
 if p_grant is true then
  if exists(select 1 from public.editor_users where user_id=p_target) then raise exception 'Already Editor' using errcode='23505';end if;
  insert into public.editor_users(user_id) values(p_target);
 elsif p_grant is false then
  delete from public.editor_users where user_id=p_target;
  if not found then raise exception 'Editor not found' using errcode='22023';end if;
  update public.editor_add_operations set state='revoked',lease=null,lease_until=null,updated_at=clock_timestamp()
    where email in (select lower(email) from auth.users where id=p_target);

 else raise exception 'Action required' using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION public.valid_quote_document(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare r record; n jsonb; a jsonb; m jsonb; ma jsonb; t text; seen text[]; total integer:=0;
begin
 if p is null then return true; end if;
 if jsonb_typeof(p)<>'object' or octet_length(p::text)>50000 then return false; end if;
 for r in with recursive walk(n,parent,depth,idx) as (
 select p,''::text,0,1::bigint union all
 select c.value,w.n->>'type',w.depth+1,c.ordinality from walk w cross join lateral jsonb_array_elements(case when jsonb_typeof(w.n->'content')='array' then w.n->'content' else '[]'::jsonb end) with ordinality c where w.depth<21
 ) select * from walk loop
 total:=total+1;n:=r.n;t:=n->>'type';a:=coalesce(n->'attrs','{}'::jsonb);
 if total>2000 or r.depth>20 or jsonb_typeof(n)<>'object' or t is null or n-array['type','attrs','content','marks','text']<>'{}'::jsonb or jsonb_typeof(a)<>'object' then return false; end if;
 if r.parent='' then if t<>'doc' then return false;end if;
 elsif r.parent='doc' then if t not in ('paragraph','heading','bulletList','orderedList') then return false;end if;
 elsif r.parent in ('paragraph','heading') then if t not in ('text','hardBreak') then return false;end if;
 elsif r.parent in ('bulletList','orderedList') then if t<>'listItem' then return false;end if;
 elsif r.parent='listItem' then if (r.idx=1 and t<>'paragraph') or (r.idx>1 and t not in ('paragraph','heading','bulletList','orderedList')) then return false;end if;
 else return false;end if;
 if a-(case when t='heading' then array['level','textAlign'] when t='paragraph' then array['textAlign'] when t='orderedList' then array['start','type'] else array[]::text[] end)<>'{}'::jsonb then return false;end if;
 if a ? 'textAlign' and a->'textAlign'<>'null'::jsonb and (jsonb_typeof(a->'textAlign')<>'string' or a->>'textAlign' not in ('left','center','right','justify')) then return false;end if;
 if t='heading' and (jsonb_typeof(a->'level') is distinct from 'number' or a->>'level' not in ('1','2','3','4','5','6')) then return false;end if;
 if t='orderedList' and ((a ? 'start' and (jsonb_typeof(a->'start')<>'number' or (a->>'start') !~ '^[0-9]+$' or (a->>'start')::numeric not between 1 and 10000)) or (a ? 'type' and a->'type'<>'null'::jsonb and a->'type'<>'"1"'::jsonb)) then return false;end if;
 if t='text' then if jsonb_typeof(n->'text') is distinct from 'string' or length(n->>'text') not between 1 and 10000 or n ? 'content' then return false;end if;
 elsif n ? 'text' then return false;end if;
 if n ? 'marks' then
 if t<>'text' or jsonb_typeof(n->'marks')<>'array' or jsonb_array_length(n->'marks')>6 then return false;end if;
 seen:=array[]::text[];
 for m in select value from jsonb_array_elements(n->'marks') loop
 ma:=coalesce(m->'attrs','{}'::jsonb);
 if jsonb_typeof(m)<>'object' or m-array['type','attrs']<>'{}'::jsonb or m->>'type' is null or m->>'type' not in ('bold','italic','underline','strike','highlight','textStyle') or m->>'type'=any(seen) or jsonb_typeof(ma)<>'object' then return false;end if;
 seen:=array_append(seen,m->>'type');
 if ma-(case when m->>'type'='textStyle' then array['color'] else array[]::text[] end)<>'{}'::jsonb then return false;end if;
 if ma ? 'color' and ma->'color'<>'null'::jsonb and (jsonb_typeof(ma->'color')<>'string' or lower(ma->>'color') not in ('#1c2845','#377f7c','#c78087','#000000')) then return false;end if;
 end loop;end if;
 if t in ('text','hardBreak') then if n ? 'content' then return false;end if;
 elsif n ? 'content' then if jsonb_typeof(n->'content')<>'array' or (t in ('listItem','bulletList','orderedList') and jsonb_array_length(n->'content')=0) then return false;end if;
 elsif t not in ('doc','paragraph','heading') then return false;end if;
 end loop;return true;
exception when others then return false;
end $function$
